public class QueryExpansionService
{
    private readonly IChatClient _llm;
    private readonly IVectorSearchService _vectorSearch;

    public async Task<List<DocumentChunk>> RetrieveAsync(
        string userQuery, int topPerQuery = 10, CancellationToken ct = default)
    {
        // Step 1: Decompose complex query into sub-questions
        var subQueries = await DecomposeQueryAsync(userQuery, ct);

        // Execute all sub-queries in parallel
        var tasks = subQueries.Select(q => _vectorSearch.SearchAsync(q, topPerQuery, ct));
        var results = await Task.WhenAll(tasks);

        // Merge and deduplicate results
        var allDocs = results.SelectMany(r => r)
            .GroupBy(d => d.Id)
            .Select(g => g.First())
            .ToList();

        // Optional: rerank the merged set
        return await RerankAsync(allDocs, userQuery, ct);
    }

    private async Task<List<string>> DecomposeQueryAsync(string query, CancellationToken ct)
    {
        var prompt = $"""
Break down the following question into simpler sub-questions that can be answered independently.
Return ONLY the sub-questions, one per line, without any additional text.

Question: {query}
Sub-questions:
""";

        var response = await _llm.CompleteAsync(prompt, cancellationToken: ct);
        return response.Message.Text
            .Split('\n', StringSplitOptions.RemoveEmptyEntries)
            .Select(q => q.Trim().Trim('-'))
            .Where(q => !string.IsNullOrEmpty(q))
            .ToList();
    }
}

public class ReciprocalRankFusion
{
    private const int K = 60; // RRF constant

    public List<ScoredDocument> Fuse(
        params IEnumerable<ScoredDocument>[] rankedLists)
    {
        var docScores = new Dictionary<string, double>();
        var docMetadata = new Dictionary<string, ScoredDocument>();

        foreach (var list in rankedLists)
        {
            var rank = 1;
            foreach (var doc in list)
            {
                var score = 1.0 / (K + rank);
                var key = doc.Document.Id?.ToString() ?? Guid.NewGuid().ToString();

                docScores[key] = docScores.GetValueOrDefault(key, 0) + score;
                docMetadata[key] = doc;
                rank++;
            }
        }

        return docScores
            .OrderByDescending(kvp => kvp.Value)
            .Select(kvp => new ScoredDocument
            {
                Document = docMetadata[kvp.Key].Document,
                Score = kvp.Value
            })
            .ToList();
    }
}
